<script setup>
// Code Generated by AI: AI helped translate the original card into a Vue template.
import dayjs from "dayjs";
defineProps({ animal: { type: Object, required: true } });
// App owns the animal data. The card asks App to change it through an event.
// If both changed the same object, responsibility would be split and it would
// be harder to trace why an animal's state changed or keep behavior consistent.
const emit = defineEmits(["toggle"]);
function arrivalText(intakeDate) {
  const arrived = dayjs(intakeDate);
  return `Arrived ${arrived.format("MMM D, YYYY")} (${dayjs().diff(arrived, "day")} days ago)`;
}
</script>

<template>
  <article class="animal-card" :class="{ adopted: animal.adopted }">
    <h3>{{ animal.name }}</h3>
    <p>{{ animal.species }}, {{ animal.age }} years old</p>
    <p>{{ arrivalText(animal.intakeDate) }}</p>
    <p>{{ animal.adopted ? "Adopted" : "Available" }}</p>
    <button type="button" @click="emit('toggle')">{{ animal.adopted ? "Return" : "Adopt" }}</button>
  </article>
</template>
